    line = line.split('#')[0].strip()
    if not line:
        continue
    m = re.match(r'^(.*?)\s*<([^<>]+)>\s*<([^<>]+)>$', line)
    if m:
        name, primary, alias = m.group(1), m.group(2).lower(), m.group(3).lower()
        mailmap[alias] = name
        mailmap[primary] = name
    else:
        m = re.match(r'^(.*?)\s*<([^<>]+)>$', line)
        if m:
            mailmap[m.group(2).lower()] = m.group(1)

