        skipped.append(('revert-commit', r['hash'][:7], head))
        continue
    m = H.fullmatch(head)
    if not m:
        skipped.append(('bad-header', r['hash'][:7], head))
        continue
    typ, scope, bang, summary = m.group(1), m.group(2) or 'general', bool(m.group(3)), m.group(4)
    if bang:
        section = 'breaking'
    elif typ == 'feat':
        section = 'feat'
    elif typ == 'fix':
        section = 'fix'
    elif typ == 'perf':
        section = 'perf'
    else:
        skipped.append(('type', r['hash'][:7], head))
        continue
    if scope == 'internal' and not bang:
        skipped.append(('internal', r['hash'][:7], head))
        continue
    # summary transform
    s = summary[0].upper() + summary[1:]
    if s.endswith('.'):
        s = s[:-1]
    if typ == 'perf' and section != 'breaking':
        s += ' [perf]'
    if scope == 'deps':
        scope = 'dependencies'
    refs = []
    if typ == 'fix':
